fd.SOURCE:
import errno,os,resource; print(resource.getrlimit(resource.RLIMIT_NOFILE)); f=[]
try:
 while True: f.append(os.open('/dev/null',os.O_RDONLY))
except OSError as e:
 print('EXPECTED_EMFILE' if e.errno==errno.EMFILE else 'UNEXPECTED:'+str(e.errno))
finally:
 for n in f: os.close(n)

file.SOURCE:
import errno,os,signal,sys; signal.signal(signal.SIGXFSZ,signal.SIG_IGN); p=sys.argv[1]; f=open(p,'wb')
try:
 for n in range(17): f.write(b'x'*1048576); f.flush()
 raise SystemExit(2)
except OSError as e: print('EXPECTED_FILE_LIMIT' if e.errno==errno.EFBIG else 'UNEXPECTED:'+str(e.errno))
finally: f.close()
assert os.path.getsize(p)<=16777216

